	if e == nil {
		return fmt.Errorf("node %q cannot adopt a nil endpoint", d.Cfg.ShortName)
	}

	owner := e.GetNode()
	if owner == nil {
		return fmt.Errorf(
			"node %q cannot adopt endpoint %q without an owner",
			d.Cfg.ShortName,
