		return nil
	}
	parkingNode := d.parkingNode
	if parkingNode == nil {
		parkingNode = clablinks.NewParkingNode(d.Cfg.LongName, parkPath)
	}

	restored, err := parkingNode.RestoreTo(ctx, d)
	if err != nil {
		return err
	}

